static void bilipai_hdr_capture_boundary(struct mp_image_params *p,
                                         const AVFrame *src)
{
    // This AVFrame may come from a decoder OR a foreign filter.
    struct mp_bilipai_hdr_snapshot s = {0};
    s.version = MP_BILIPAI_HDR_SNAPSHOT_VERSION;
    s.av_format = s.av_sw_format = src->format;
    if (src->hw_frames_ctx && src->hw_frames_ctx->data) {
        const AVHWFramesContext *hw = (const void *)src->hw_frames_ctx->data;
        s.av_sw_format = hw->sw_format;
    }
    s.width = src->width;
    s.height = src->height;
    s.av_matrix = src->colorspace;
    s.av_range = src->color_range;
    s.av_primaries = src->color_primaries;
    s.av_transfer = src->color_trc;
    s.av_chroma = src->chroma_location;
    const AVFrameSideData *mdm = NULL, *cll = NULL;
    for (int n = 0; n < src->nb_side_data; n++) {
        const AVFrameSideData *sd = src->side_data[n];
        switch (sd->type) {
        case AV_FRAME_DATA_MASTERING_DISPLAY_METADATA:
            s.flags |= MP_BILIPAI_HDR_MDM_PRESENT;
            s.mdm_count++;
            if (!mdm) { mdm = sd; s.mdm_size = sd->size; }
            break;
        case AV_FRAME_DATA_CONTENT_LIGHT_LEVEL:
            s.flags |= MP_BILIPAI_HDR_CLL_PRESENT;
            s.cll_count++;
            if (!cll) { cll = sd; s.cll_size = sd->size; }
            break;
        case AV_FRAME_DATA_DYNAMIC_HDR_PLUS:
            s.flags |= MP_BILIPAI_HDR_PLUS_PRESENT;
            break;
        case AV_FRAME_DATA_DYNAMIC_HDR_VIVID:
            s.flags |= MP_BILIPAI_HDR_VIVID_PRESENT;
            break;
        case AV_FRAME_DATA_DYNAMIC_HDR_SMPTE_2094_APP5:
            s.flags |= MP_BILIPAI_HDR_APP5_PRESENT;
            break;
        case AV_FRAME_DATA_DOVI_METADATA:
            s.flags |= MP_BILIPAI_HDR_DOVI_METADATA_PRESENT;
            break;
        case AV_FRAME_DATA_DOVI_RPU_BUFFER:
            s.flags |= MP_BILIPAI_HDR_DOVI_RPU_PRESENT;
            break;
        case AV_FRAME_DATA_ICC_PROFILE:
            s.flags |= MP_BILIPAI_HDR_ICC_PRESENT;
            break;
        default:
            break;
        }
    }
    if (s.mdm_count > 1 || s.cll_count > 1)
        s.flags |= MP_BILIPAI_HDR_DUPLICATE_STATIC;
    if (mdm) {
        // Fixed FFmpeg9fc8 layout only. Unknown size cannot be dereferenced.
        if (!mdm->data || mdm->size != sizeof(AVMasteringDisplayMetadata)) {
            s.flags |= MP_BILIPAI_HDR_MDM_SIZE_UNKNOWN;
        } else {
            AVMasteringDisplayMetadata m;
            memcpy(&m, mdm->data, sizeof(m));
            s.flags |= MP_BILIPAI_HDR_MDM_PARSED;
            s.has_primaries = m.has_primaries;
            s.has_luminance = m.has_luminance;
            for (int c = 0; c < 3; c++) {
                for (int xy = 0; xy < 2; xy++) {
                    s.display_primaries[c][xy] = bilipai_hdr_rational(m.display_primaries[c][xy]);
                    if (m.has_primaries && m.display_primaries[c][xy].den <= 0)
                        s.flags |= MP_BILIPAI_HDR_MDM_RATIONAL_INVALID;
                }
            }
            for (int xy = 0; xy < 2; xy++) {
                s.white_point[xy] = bilipai_hdr_rational(m.white_point[xy]);
                if (m.has_primaries && m.white_point[xy].den <= 0)
                    s.flags |= MP_BILIPAI_HDR_MDM_RATIONAL_INVALID;
            }
            s.min_luminance = bilipai_hdr_rational(m.min_luminance);
            s.max_luminance = bilipai_hdr_rational(m.max_luminance);
            if (m.has_luminance && (m.min_luminance.den <= 0 || m.max_luminance.den <= 0))
                s.flags |= MP_BILIPAI_HDR_MDM_RATIONAL_INVALID;
            if ((m.has_primaries != 0 && m.has_primaries != 1) ||
                (m.has_luminance != 0 && m.has_luminance != 1))
                s.flags |= MP_BILIPAI_HDR_MDM_FLAGS_NONBOOLEAN;
        }
    }
    if (cll) {
        if (!cll->data || cll->size != sizeof(AVContentLightMetadata)) {
            s.flags |= MP_BILIPAI_HDR_CLL_SIZE_UNKNOWN;
        } else {
            AVContentLightMetadata c;
            memcpy(&c, cll->data, sizeof(c));
            s.flags |= MP_BILIPAI_HDR_CLL_PARSED;
            s.max_cll = c.MaxCLL;
            s.max_fall = c.MaxFALL;
        }
    }
    p->bilipai_hdr_snapshot = s;
    p->bilipai_hdr_observed_flags = s.flags;
    p->bilipai_hdr_snapshot_relation = MP_BILIPAI_HDR_SNAPSHOT_AVFRAME_BOUNDARY;
    p->bilipai_hdr_current_encoding = MP_BILIPAI_HDR_CURRENT_UNKNOWN;
}

// Create a new mp_image reference to av_frame.

if (p->bilipai_hdr_snapshot.version == MP_BILIPAI_HDR_SNAPSHOT_VERSION) {
    // Preserve history when export generated MDM from inferred hdr.
    // Neither opaque tag nor this record proves current pixels.
    dst->params.bilipai_hdr_snapshot = p->bilipai_hdr_snapshot;
    dst->params.bilipai_hdr_snapshot_relation =
