void mp_image_params_bilipai_hdr_copy_history(struct mp_image_params *dst,
                                              const struct mp_image_params *src)
{
    struct mp_bilipai_hdr_snapshot s = {0};
    if (src->bilipai_hdr_snapshot.version == MP_BILIPAI_HDR_SNAPSHOT_VERSION)
        s = src->bilipai_hdr_snapshot;
    // Compute before assignment so even aliasing cannot erase refusal facts.
    uint32_t hazards = src->bilipai_hdr_disqualifying_flags_seen |
        ((src->bilipai_hdr_observed_flags | src->bilipai_hdr_snapshot.flags) &
         MP_BILIPAI_HDR_HAZARDS_MASK);
    dst->bilipai_hdr_snapshot = s;
    dst->bilipai_hdr_snapshot_relation = s.version == MP_BILIPAI_HDR_SNAPSHOT_VERSION ?
        MP_BILIPAI_HDR_SNAPSHOT_ATTRIBUTE_HISTORY : MP_BILIPAI_HDR_SNAPSHOT_NONE;
    dst->bilipai_hdr_disqualifying_flags_seen = hazards;
    dst->bilipai_hdr_observed_flags = 0;
    dst->bilipai_hdr_current_encoding = MP_BILIPAI_HDR_CURRENT_UNKNOWN;
}

