static void bilipai_step(struct priv *p)
{
    if (p->bilipai_feedback.serial >= INT64_MAX) {
        p->bilipai_counter_failed = true;
        p->bilipai_feedback.queued.valid = p->bilipai_feedback.displayed.valid = false;
        return;
    }
    ++p->bilipai_feedback.serial;
}
static void bilipai_invalidate(struct priv *p, uint32_t reason, bool epoch)
{
    p->bilipai_pending = (struct mp_bilipai_render_receipt){0};
    memset(p->bilipai_ring, 0, sizeof(p->bilipai_ring));
    p->bilipai_ring_next = 0;
    p->bilipai_feedback.queued.valid = p->bilipai_feedback.displayed.valid = false;
    p->bilipai_feedback.reason = reason;
    if (epoch) {
        if (p->bilipai_feedback.epoch >= INT64_MAX)
            p->bilipai_counter_failed = true;
        else
            ++p->bilipai_feedback.epoch;
    }
    bilipai_step(p);
}
struct bilipai_fullscreen_probe { RECT monitor; bool foreign_fullscreen; };
static BOOL CALLBACK bilipai_foreign_fullscreen(HWND w, LPARAM opaque)
{
    struct bilipai_fullscreen_probe *p = (void *)opaque;
    DWORD pid = 0; RECT r;
    GetWindowThreadProcessId(w, &pid);
    if (pid && pid != GetCurrentProcessId() && IsWindowVisible(w) &&
        !IsIconic(w) && GetWindowRect(w, &r) &&
        r.left <= p->monitor.left && r.top <= p->monitor.top &&
        r.right >= p->monitor.right && r.bottom >= p->monitor.bottom)
        p->foreign_fullscreen = true;
    return TRUE;
}
static bool bilipai_statistics_environment(struct ra_swapchain *sw)
{
    struct priv *p = sw->priv;
    if (p->opts->sync_interval != 1 || sw->ctx->opts.composition ||
        GetSystemMetrics(SM_CMONITORS) != 1)
        return false;
    HWND w = vo_w32_hwnd(sw->ctx->vo);
    HMONITOR mon = MonitorFromWindow(w, MONITOR_DEFAULTTONULL);
    MONITORINFO info = {.cbSize = sizeof(info)};
    DXGI_SWAP_CHAIN_DESC desc = {0};
    if (!w || !mon || mon != p->bilipai_monitor ||
        !GetMonitorInfo(mon, &info) ||
        IDXGISwapChain_GetDesc(p->swapchain, &desc) != S_OK ||
        (desc.SwapEffect != DXGI_SWAP_EFFECT_FLIP_SEQUENTIAL &&
         desc.SwapEffect != DXGI_SWAP_EFFECT_FLIP_DISCARD))
        return false;
    struct bilipai_fullscreen_probe probe = {.monitor = info.rcMonitor};
    return EnumWindows(bilipai_foreign_fullscreen, (LPARAM)&probe) &&
           !probe.foreign_fullscreen;
}
static bool bilipai_output(struct ra_swapchain *sw,
                          const struct mp_bilipai_render_receipt *r,
                          struct mp_bilipai_present_receipt *out)
{
    struct priv *p = sw->priv;
    DXGI_SWAP_CHAIN_DESC desc = {0};
    if (!r->fresh || !mp_bilipai_token_valid(&r->token) ||
        !p->bilipai_color_configured || !p->bilipai_adapter_luid ||
        r->token.adapter_luid != p->bilipai_adapter_luid ||
        r->target_transfer != p->swapchain_csp.transfer ||
        r->target_primaries != p->swapchain_csp.primaries ||
        r->framebuffer_transfer != p->swapchain_csp.transfer ||
        r->framebuffer_primaries != p->swapchain_csp.primaries ||
        IDXGISwapChain_GetDesc(p->swapchain, &desc) != S_OK)
        return false;
    bool hdr = !!(r->token.effects & MP_BILIPAI_EFFECT_HDR);
    bool hdr_proved = false;
    if (hdr) {
        DXGI_OUTPUT_DESC1 display = {0};
        bool hdr_encoding =
            (desc.BufferDesc.Format == DXGI_FORMAT_R10G10B10A2_UNORM &&
             p->bilipai_dxgi_csp == DXGI_COLOR_SPACE_RGB_FULL_G2084_NONE_P2020) ||
            (desc.BufferDesc.Format == DXGI_FORMAT_R16G16B16A16_FLOAT &&
             p->bilipai_dxgi_csp == DXGI_COLOR_SPACE_RGB_FULL_G10_NONE_P709);
        hdr_proved = hdr_encoding && !sw->ctx->opts.composition &&
            mp_dxgi_output_desc_from_hwnd(&p->dxgi_ctx, vo_w32_hwnd(sw->ctx->vo), &display) &&
            display.ColorSpace == DXGI_COLOR_SPACE_RGB_FULL_G2084_NONE_P2020;
        if (!hdr_proved) return false;
    }
    *out = (struct mp_bilipai_present_receipt){
        .render = *r, .epoch = p->bilipai_feedback.epoch,
        .dxgi_format = desc.BufferDesc.Format, .dxgi_color_space = p->bilipai_dxgi_csp,
        .hdr_output_proved = hdr_proved,
    };
    return true;
}
